(function () {
    var loading = document.getElementById('loading');
    function inflate(b64) {
        var bin = atob(b64), bytes = new Uint8Array(bin.length);
        for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
        return new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).text();
    }
    inflate("").then(function (code) {
        return new Promise(function (resolve, reject) {
            var script = document.createElement('script');
            script.src = URL.createObjectURL(new Blob([code], { type: 'text/javascript' }));
            script.onload = function () { URL.revokeObjectURL(script.src); resolve(); };
            script.onerror = reject;
            document.head.appendChild(script);
        });
    }).then(function () {
        var E = window.Engine3DRunner;
        var platform = window.Platform = E.createPlatform({"platform":"discord","discordClientId":"1561407060728479814"});
        return platform.ready().then(function () {
            platform.loadingProgress(0.3);
            return inflate("");
        }).then(function (sceneJson) {
            platform.loadingProgress(0.6);
            return E.initGame(document.getElementById('app-canvas'), JSON.parse(sceneJson));
        }).then(function (app) {
            platform.loadingProgress(1);
            return platform.start(app);
        }).then(function () {
            loading.remove();
        });
    }).catch(function (err) {
        loading.textContent = 'This game could not start.';
        console.error(err);
    });
})();